package com.myeshopping.cartonization;
import org.springframework.boot.*; import org.springframework.boot.autoconfigure.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@SpringBootApplication @RestController @RequestMapping("/api/v1/cartonization") public class CartonizationApplication { private final Map<Long,Map<String,Object>> plans=new HashMap<>(); public static void main(String[]a){SpringApplication.run(CartonizationApplication.class,a);} @PostMapping("/{orderId}") public Map<String,Object> plan(@PathVariable Long orderId,@RequestParam(defaultValue="1") int itemCount){Map<String,Object> p=new LinkedHashMap<>();p.put("orderId",orderId);p.put("cartonCount",Math.max(1,(itemCount+4)/5));p.put("status","PLANNED");plans.put(orderId,p);return p;} @GetMapping("/{orderId}") public Map<String,Object> get(@PathVariable Long orderId){return Optional.ofNullable(plans.get(orderId)).orElseThrow(()->new IllegalArgumentException("Carton plan not found"));} }
